        elif side == "left":
            vals = [grid[r][0] for r in range(h)]
        else:
            vals = [grid[r][w - 1] for r in range(h)]

        i = 0
        while i < len(vals):
            if vals[i] == bg:
                i += 1
                continue
            color = vals[i]
            j = i + 1
            while j < len(vals) and vals[j] == color:
                j += 1
            if j - i >= 2:
                runs.append((side, i, j, color))
            i = j

    opposite = {
        "top": "bottom", "bottom": "top",
        "left": "right", "right": "left"
    }
    pairs = []
    for a in runs:
        for b in runs:
            if (opposite[a[0]] == b[0] and a[3] == b[3]
                    and a[2] - a[1] == b[2] - b[1]):
                pairs.append((a, b))

    if not pairs:
        return out

    a, b = max(pairs, key=lambda p: p[0][2] - p[0][1])
    bar_color = a[3]

    counts = Counter(
        grid[r][c]
        for r in range(h) for c in range(w)
        if grid[r][c] != bg and grid[r][c] != bar_color
    )
    if not counts:
        return out
    signal = counts.most_common(1)[0][0]

    def along_coordinate(r, c, side):
        return c if side in ("top", "bottom") else r

    # Mark offsets within a border segment where signal pixels occur.
    offsets = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != signal:
                continue
            for seg in (a, b):
                side, start, end, _ = seg
                q = along_coordinate(r, c, side)
                if start <= q < end:
                    offsets.add(q - start)
                    break

    # Extend each marked track inward from both border bars, stopping at
    # a signal pixel. Any signal pixels are finally marked with color 4.
    for side, start, end, _ in (a, b):
        for offset in offsets:
            q = start + offset
            if q >= end:
                continue

            if side == "top":
                cells = ((r, q) for r in range(1, h))
            elif side == "bottom":
                cells = ((r, q) for r in range(h - 2, -1, -1))
            elif side == "left":
                cells = ((q, c) for c in range(1, w))
            else:
                cells = ((q, c) for c in range(w - 2, -1, -1))

            for r, c in cells:
                value = grid[r][c]
                if value == signal:
                    break
                if value == bar_color:
                    break
                if value == bg:
                    out[r][c] = signal

    for r in range(h):
        for c in range(w):
            if grid[r][c] == signal:
                out[r][c] = 4

    return out
